import {
	Accessor,
	createEffect,
	createMemo,
	createSignal,
	JSX,
	ParentComponent,
	splitProps,
	useContext,
} from "solid-js";
import { createStore } from "solid-js/store";

import { GameActionName } from "#core/ui-next/services/actionButtons.js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { AudioGroupContext } from "#core/ui-next/services/audio.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyArgs, NavTrayArgs, registerHotkey, registerNavTray } from "#core/ui-next/services/hotkey.js";

import { InputEngineEvent } from "../../../core/ui/input/input-support";

export interface GamepadTrayItemAudio {
	/** Audio override for when the activatable finishes activating */
	onActivate?: string;
	/** Audio override for when the activatable starts activating */
	onPress?: string;
	/** Audio override for when the activatable is unable to activate */
	onError?: string;
}

export interface GamepadTrayItem {
	/** The name of the gamepad tray item; set as the data-name property in an inner div in the Activatable component -
	 * useful for debugging or searching the DOM tree. */
	name: string;
	/** The name of a hotkey action which activates this component. */
	hotkeyAction: GameActionName;
	/** The text which appears on the navTray with the given hotkeyAction. */
	navTrayText: string;
	/** Event which triggers when the control is activated through hotkey. Leave undefined to show an item in the
	 * tray that is handled elswhere */
	onActivate?: () => void;
	/** Audio overrides for this item - See {@link GamepadTrayItemAudio} for a full list. */
	audio?: GamepadTrayItemAudio;
}

interface GamepadTrayItemProviderProps extends JSX.HTMLAttributes<HTMLDivElement> {
	name: string;
	items: Accessor<GamepadTrayItem[]>;
	enabled?: Accessor<boolean>;
}
const GamepadTrayItemProviderComponent: ParentComponent<GamepadTrayItemProviderProps> = (props) => {
	const [root, setRoot] = createSignal<HTMLDivElement>();
	const [args, setArgs] = createStore<{ hotkeyArgs: HotkeyArgs; navTrayArgs: NavTrayArgs }[]>([]);
	const audioContext = useContext(AudioGroupContext);
	const audioTrigger = useAudio();

	const [localProps, divProps] = splitProps(props, ["name", "items", "enabled"]);

	const enabled = createMemo(() => localProps.enabled ?? (() => true));
	createEffect(() => {
		const result: { hotkeyArgs: HotkeyArgs; navTrayArgs: NavTrayArgs }[] = [];
		localProps.items().forEach((item) => {
			result.push({
				hotkeyArgs: () => [item.hotkeyAction, enabled(), item.onActivate],
				navTrayArgs: () => [item.hotkeyAction, enabled(), item.navTrayText],
			});
		});
		setArgs(result);
	});

	createEffect(() => {
		if (!root()) {
			return;
		}
		args.forEach((arg) => {
			registerHotkey(root()!, arg.hotkeyArgs);
			registerNavTray(root()!, arg.navTrayArgs);
		});
	});

	// Only trigger audio if the provided attribute is not defined.  This is to prevent duplicate audio from playing.
	function triggerAudioIfAttributeNotDefined(eventName: string, attributeName: string) {
		if (!root()?.hasAttribute(attributeName)) {
			audioTrigger(localProps.name, eventName);
		}
	}

	const onEngineInput = (inputEvent: InputEngineEvent) => {
		const isStart = inputEvent.detail.status == InputActionStatuses.START;
		const isFinish = inputEvent.detail.status == InputActionStatuses.FINISH;

		if (!isStart && !isFinish) {
			return;
		}

		let handleActivate: (() => void) | undefined = undefined;
		if (localProps.items().length > 0) {
			const item = localProps.items().find((trayItem) => trayItem.hotkeyAction === inputEvent.detail.name);
			if (item) {
				handleActivate = item.onActivate;
			}
		}

		if (handleActivate) {
			if (!enabled()()) {
				if (isStart) {
					audioContext().playSound("data-audio-error-press", root());
					triggerAudioIfAttributeNotDefined("pressError", "data-audio-error-press");
				}
			} else {
				if (isStart) {
					audioContext().playSound("data-audio-press", root());
					triggerAudioIfAttributeNotDefined("press", "data-audio-press");
				} else {
					audioContext().playSound("data-audio-activate", root());
					triggerAudioIfAttributeNotDefined("activate", "data-audio-activate");
					handleActivate?.();

					inputEvent.preventDefault();
					inputEvent.stopPropagation();
				}
			}
		}
	};

	return (
		<div
			{...divProps}
			data-name={localProps.name}
			ref={setRoot}
			on:engine-input={onEngineInput}
		>
			{props.children}
		</div>
	);
};

export const GamepadTrayItemProvider = ComponentRegistry.register({
	name: "GamepadTrayItemProvider",
	createInstance: GamepadTrayItemProviderComponent,
});
